import java.util.*;
class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        List<List<Integer>> ans = new ArrayList<>();
        dfs(candidates, 0, target, new ArrayList<>(), ans);
        return ans;
    }
    private void dfs(int[] a, int start, int left, List<Integer> path, List<List<Integer>> ans) {
        if (left == 0) { ans.add(new ArrayList<>(path)); return; }
        for (int i = start; i < a.length; i++) {
            if (a[i] > left) continue;
            path.add(a[i]);
            dfs(a, i, left - a[i], path, ans);
            path.remove(path.size() - 1);
        }
    }
}

