import java.util.*;
class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> ans = new ArrayList<>();
        dfs(n, 0, 0, new StringBuilder(), ans);
        return ans;
    }
    private void dfs(int n, int open, int close, StringBuilder s, List<String> ans) {
        if (s.length() == 2 * n) { ans.add(s.toString()); return; }
        if (open < n) {
            s.append('('); dfs(n, open + 1, close, s, ans); s.deleteCharAt(s.length() - 1);
        }
        if (close < open) {
            s.append(')'); dfs(n, open, close + 1, s, ans); s.deleteCharAt(s.length() - 1);
        }
    }
}

