class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> ans = new ArrayList<>();
        boolean[] col = new boolean[n], diag1 = new boolean[2*n], diag2 = new boolean[2*n];
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        dfs(0, n, board, col, diag1, diag2, ans);
        return ans;
    }
    private void dfs(int r, int n, char[][] b, boolean[] c, boolean[] d1, boolean[] d2, List<List<String>> ans) {
        if (r == n) { List<String> out = new ArrayList<>(); for (char[] row : b) out.add(new String(row)); ans.add(out); return; }
        for (int j = 0; j < n; j++) {
            int a = r-j+n, z = r+j;
            if (c[j] || d1[a] || d2[z]) continue;
            c[j] = d1[a] = d2[z] = true; b[r][j] = 'Q';
            dfs(r+1,n,b,c,d1,d2,ans);
            b[r][j] = '.'; c[j] = d1[a] = d2[z] = false;
        }
    }
}

