public class Codec {
    public String serialize(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        write(root,sb);
        return sb.toString();
    }
    private void write(TreeNode node, StringBuilder sb) {
        if (node == null) { sb.append("#,"); return; }
        sb.append(node.val).append(',');
        write(node.left,sb); write(node.right,sb);
    }
    public TreeNode deserialize(String data) {
        Deque<String> q = new ArrayDeque<>(Arrays.asList(data.split(",")));
        return read(q);
    }
    private TreeNode read(Deque<String> q) {
        String x = q.removeFirst();
        if (x.equals("#")) return null;
        TreeNode node = new TreeNode(Integer.parseInt(x));
        node.left = read(q); node.right = read(q);
        return node;
    }
}

