                for(int[] d:dirs){
                    int r=cur[0]+d[0],c=cur[1]+d[1];
                    if(r>=0&&c>=0&&r<grid.length&&c<grid[0].length&&grid[r][c]==1){
                        grid[r][c]=2;fresh--;q.offer(new int[]{r,c});
                    }
                }
            }
